    rd = csv.reader(f)
    hdr = [h.strip() for h in next(rd)]
    rows = [r for r in rd if r and any(x.strip() for x in r)]
print('HDR:', hdr)
print('N:', len(rows))
for r in rows[:4]:
    print(r)
print('...')
for r in rows[-2:]:
    print(r)

def fnum(x):
    try: return float(str(x).replace(',',''))
    except Exception: return None

idx = {}
for j,h in enumerate(hdr):
    hl = h.lower()
    if 'diag' in hl: idx['diag']=j
    elif 'year' in hl: idx['year']=j
    elif 'month' in hl or 'duration' in hl: idx['month']=j
    elif 'recov' in hl or 'termin' in hl or 'actual' in hl: idx['act']=j
    elif 'expect' in hl: idx['exp']=j
    elif 'expos' in hl: idx['expo']=j
    elif 'rate' in hl: idx['rate']=j
    elif 'ae' in hl: idx['ae']=j
print('IDX:', idx)

byy = {}
for r in rows:
    d = r[idx['diag']] if 'diag' in idx else ''
    if 'mental' not in d.lower(): continue
    y = r[idx['year']] if 'year' in idx else 'ALL'
    if 'act' in idx and 'exp' in idx:
        a=fnum(r[idx['act']]); e=fnum(r[idx['exp']])
        if a is not None and e is not None:
            s=byy.setdefault(y,[0.0,0.0]); s[0]+=a; s[1]+=e
    elif 'ae' in idx:
        a=fnum(r[idx['ae']])
        w=fnum(r[idx['expo']]) if 'expo' in idx else 1.0
        if a is not None and w:
            s=byy.setdefault(y,[0.0,0.0]); s[0]+=a*w; s[1]+=w
print('MH by year (A/E, actual, expected):')
for y in sorted(byy):
    a,e = byy[y]
    if e: print(y, round(a/e,3), round(a), round(e))

agg={}
for r in rows:
    d = r[idx['diag']]
    if 'act' in idx and 'exp' in idx:
        a=fnum(r[idx['act']]); e=fnum(r[idx['exp']])
        if a is not None and e is not None:
            s=agg.setdefault(d,[0.0,0.0]); s[0]+=a; s[1]+=e
